<?php
namespace App\Controllers\Api\V1;
use App\Core\ApiController; use App\Services\Communication\NotificationMessageService; use App\Validation\NotificationMessageValidation; use Throwable;
class NotificationMessageController extends ApiController { public function __construct(private readonly NotificationMessageService $service=new NotificationMessageService()){} public function index(){try{return $this->ok('Notification message listesi getirildi',$this->service->list($this->request->getGet()));}catch(Throwable $e){return $this->failFromException($e);}} public function create(){try{$p=$this->apiValidator->validateOrFail($this->request->getJSON(true)??[],NotificationMessageValidation::createRules()); return $this->ok('Notification message olusturuldu',$this->service->create($p));}catch(Throwable $e){return $this->failFromException($e);}} public function show($id=null){try{return $this->ok('Notification message getirildi',$this->service->show((int)$id));}catch(Throwable $e){return $this->failFromException($e);}} public function queue($id=null){try{return $this->ok('Notification message queue edildi',$this->service->queue((int)$id));}catch(Throwable $e){return $this->failFromException($e);}} public function cancel($id=null){try{return $this->ok('Notification message iptal edildi',$this->service->cancel((int)$id));}catch(Throwable $e){return $this->failFromException($e);}} }
